// Package cohort is the rewards platform's contract for cohort providers: plugins, written by growth teams in Go,
// Lua or TypeScript, that say which users a campaign targets. A provider answers bounded questions (is this user a
// member, and the members a page at a time), never the whole cohort in one call, and may read the platform's user
// directory through its Host, [Users]. provider_plg.go is generated by the line below (`go generate ./...`).
package cohort

//go:generate go run github.com/heynemann/go-plg/cmd/plg gen Provider

import "context"

// MaxPageSize is the most users a page of a cohort, or of the directory, may hold: the platform rejects a larger
// page from a provider, and the directory serves no larger one.
const MaxPageSize = 500

// Page is one page of a cohort: some of its members, by user ID, and the cursor of the next page ("" after the
// last page). A page may be empty while later pages are not.
type Page struct {
	Next  string   `json:"next"`
	Users []string `json:"users"`
}

// User is a user of the platform's directory.
type User struct {
	// ID identifies the user; the directory orders users by it.
	ID string `json:"id"`
	// Country is the user's ISO 3166-1 alpha-2 country code.
	Country string `json:"country"`
	// Tier is the user's loyalty tier: "gold", "silver" or "bronze".
	Tier string `json:"tier"`
	// SpendCents is what the user spent in the last year, in cents.
	SpendCents int64 `json:"spendCents"`
	// Orders is how many orders the user placed in the last year.
	Orders int `json:"orders"`
}

// UserPage is one page of the directory: users in ID order, and the cursor of the next page ("" after the last).
type UserPage struct {
	Next  string `json:"next"`
	Users []User `json:"users"`
}

// Provider is a cohort: a set of users a campaign targets.
//
//plg:limits memory=128MiB timeout=5s pool=1..4
type Provider interface {
	// IsMember reports whether user is in the cohort.
	IsMember(ctx context.Context, user string) (bool, error)
	// List returns the page of the cohort at cursor: "" for the first page, then the Next of the page before.
	List(ctx context.Context, cursor string) (Page, error)
}

// Users is the platform's user directory, the Host cohort providers may call (plg.WithHost[cohort.Users]).
type Users interface {
	// Lookup returns the user of the ID; a User with an empty ID when the directory has none.
	Lookup(ctx context.Context, id string) (User, error)
	// Page returns at most limit users (1 to MaxPageSize) whose IDs come after cursor ("" for the first page).
	Page(ctx context.Context, cursor string, limit int) (UserPage, error)
}
